add("vsa1", ("इलेक्ट्रॉनों के स्थानांतरण द्वारा सोडियम क्लोराइड का निर्माण दर्शाइए।", "ઇલેક્ટ્રૉનની ફેરબદલી વડે સોડિયમ ક્લોરાઇડનું નિર્માણ દર્શાવો."),
    {0: ("सोडियम एक इलेक्ट्रॉन खोता है: {0}", "સોડિયમ એક ઇલેક્ટ્રૉન ગુમાવે છે: {0}"), 1: ("क्लोरीन उसे ग्रहण करता है: {0}। विपरीत आवेशित आयन आकर्षित होकर Na⁺Cl⁻ बनाते हैं।", "ક્લોરિન તેને મેળવે છે: {0}. વિરુદ્ધ વિદ્યુતભારિત આયનો આકર્ષાઈને Na⁺Cl⁻ બનાવે છે.")})
add("vsa2", ("थर्मिट अभिक्रिया क्या है? इसका एक उपयोग बताइए।", "થર્માઇટ પ્રક્રિયા એટલે શું? તેનો એક ઉપયોગ જણાવો."),
    {0: ("ऐलुमिनियम द्वारा आयरन ऑक्साइड का अत्यधिक ऊष्माक्षेपी अपचयन: {0}", "ઍલ્યુમિનિયમ વડે આયર્ન ઑક્સાઇડનું અત્યંત ઉષ્માક્ષેપક રિડક્શન: {0}"), 1: ("पिघले लोहे से रेल की पटरियाँ और टूटे मशीनी पुर्ज़े जोड़े जाते हैं।", "પીગળેલા લોખંડથી રેલના પાટા અને તૂટેલા યંત્રના ભાગ જોડાય છે.")})
add("sa1", ("पारा उसके अयस्क सिनेबार से कैसे प्राप्त किया जाता है? समीकरण लिखिए।", "પારો તેના ધાતુખનિજ સિનેબારમાંથી કેવી રીતે મેળવાય છે? સમીકરણ લખો."),
    {0: ("पारा सक्रियता श्रेणी में नीचे है, इसलिए केवल गर्म करना पर्याप्त है।", "પારો સક્રિયતા શ્રેણીમાં નીચે છે, તેથી ફક્ત ગરમ કરવું પૂરતું છે."), 1: ("सिनेबार को वायु में गर्म किया जाता है: {0}", "સિનેબારને હવામાં ગરમ કરાય છે: {0}"), 2: ("और गर्म करने पर मर्क्यूरी ऑक्साइड वियोजित होता है: {0}", "વધુ ગરમ કરતાં મર્ક્યુરી ઑક્સાઇડનું વિઘટન થાય છે: {0}")})
add("sa2", ("मैग्नीशियम, पोटैशियम, ताँबा और ज़िंक को अभिक्रियाशीलता के घटते क्रम में व्यवस्थित कीजिए। कॉपर सल्फ़ेट विलयन में ज़िंक डालने पर क्या दिखेगा? समीकरण लिखिए।", "મૅગ્નેશિયમ, પોટૅશિયમ, તાંબું અને ઝિંકને ઘટતી સક્રિયતાના ક્રમમાં ગોઠવો. કૉપર સલ્ફેટના દ્રાવણમાં ઝિંક ઉમેરતાં શું જોવા મળશે? સમીકરણ લખો."),
    {0: ("K > Mg > Zn > Cu।", "K > Mg > Zn > Cu."), 1: ("विलयन का नीला रंग फीका पड़ जाता है और ज़िंक पर कॉपर की लाल-भूरी परत बनती है।", "દ્રાવણનો વાદળી રંગ ઝાંખો થાય છે અને ઝિંક પર કૉપરનું લાલાશ પડતું બદામી પડ બને છે.")})
add("la1", ("ताँबे के विद्युत अपघटनी परिष्करण का वर्णन कीजिए। ऐनोड पंक क्या है?", "તાંબાના વિદ્યુતવિભાજનીય શુદ્ધીકરણનું વર્ણન કરો. ઍનોડ પંક એટલે શું?"),
    {0: ("ऐनोड अशुद्ध ताँबे का मोटा टुकड़ा है; कैथोड शुद्ध ताँबे की पतली पट्टी है।", "ઍનોડ અશુદ્ધ તાંબાનો જાડો ટુકડો છે; કૅથોડ શુદ્ધ તાંબાની પાતળી પટ્ટી છે."), 1: ("विद्युत अपघट्य अम्लीकृत कॉपर सल्फ़ेट विलयन है।", "વિદ્યુતવિભાજ્ય ઍસિડયુક્ત કૉપર સલ્ફેટનું દ્રાવણ છે."),
     2: ("धारा प्रवाहित होने पर ऐनोड से ताँबा विलयन में घुलता है, और उतना ही शुद्ध ताँबा कैथोड पर जमता है।", "પ્રવાહ પસાર થતાં ઍનોડમાંથી તાંબું દ્રાવણમાં ઓગળે છે, અને એટલું જ શુદ્ધ તાંબું કૅથોડ પર જમા થાય છે."),
     3: ("विलेय अशुद्धियाँ विलयन में चली जाती हैं।", "દ્રાવ્ય અશુદ્ધિઓ દ્રાવણમાં જાય છે."), 4: ("अविलेय अशुद्धियाँ, जैसे चाँदी और सोना, ऐनोड के नीचे बैठ जाती हैं: यह ऐनोड पंक है।", "અદ્રાવ્ય અશુદ્ધિઓ, જેમ કે ચાંદી અને સોનું, ઍનોડની નીચે ઠરે છે: આ ઍનોડ પંક છે.")})
add("la2", ("समीकरणों सहित ज़िंक जैसी मध्यम सक्रियता वाली धातु का (i) उसके सल्फ़ाइड अयस्क (ii) उसके कार्बोनेट अयस्क से निष्कर्षण समझाइए। सोडियम के निष्कर्षण में कार्बन का प्रयोग क्यों नहीं किया जा सकता?",
            "સમીકરણો સાથે ઝિંક જેવી મધ્યમ સક્રિયતાવાળી ધાતુનું (i) તેના સલ્ફાઇડ ધાતુખનિજ (ii) તેના કાર્બોનેટ ધાતુખનિજમાંથી નિષ્કર્ષણ સમજાવો. સોડિયમના નિષ્કર્ષણમાં કાર્બન કેમ વાપરી શકાતો નથી?"),
    {0: ("(i) ज़िंक ब्लेंड का भर्जन किया जाता है: {0}", "(i) ઝિંક બ્લેન્ડનું ભૂંજન કરાય છે: {0}"), 1: ("(ii) कैलामाइन का निस्तापन किया जाता है: {0}", "(ii) કૅલેમાઇનનું ભસ્મીકરણ કરાય છે: {0}"),
     2: ("ज़िंक ऑक्साइड को कार्बन से अपचयित किया जाता है: {0}", "ઝિંક ઑક્સાઇડનું કાર્બન વડે રિડક્શન કરાય છે: {0}"), 3: ("ज़िंक को विद्युत अपघटनी परिष्करण से शुद्ध किया जा सकता है।", "ઝિંકને વિદ્યુતવિભાજનીય શુદ્ધીકરણ વડે શુદ્ધ કરી શકાય છે."),
     4: ("सोडियम कार्बन से अधिक सक्रिय है और ऑक्सीजन के प्रति उसकी बंधुता अधिक है, इसलिए कार्बन उसके यौगिकों को अपचयित नहीं कर सकता; विद्युत अपघटन किया जाता है।", "સોડિયમ કાર્બન કરતાં વધુ સક્રિય છે અને ઑક્સિજન પ્રત્યે તેનું આકર્ષણ વધુ છે, તેથી કાર્બન તેનાં સંયોજનોનું રિડક્શન કરી શકતો નથી; વિદ્યુતવિભાજન કરાય છે.")})
add("cb1", ("नेहा का विद्यालय समुद्र के पास है। लोहे का गेट जल्दी जंग खा जाता है, पर 'स्टेनलेस' लिखी स्टील की रेलिंग नहीं। बिजली मिस्त्री तार जोड़ने के लिए सोल्डर का प्रयोग करता है, और उसकी दादी की चूड़ियाँ 22 कैरेट सोने की हैं।\n\n"
            "(i) लोहे में जंग लगने के लिए कौन-सी दो परिस्थितियाँ आवश्यक हैं? (1)\n\n(ii) स्टेनलेस स्टील में लोहे के साथ मिलाई गई धातुओं के नाम बताइए। (1)\n\n(iii) सोल्डर बिजली के तार जोड़ने के लिए उपयुक्त क्यों है? अथवा आभूषणों में 24 कैरेट के बजाय 22 कैरेट सोना क्यों प्रयोग होता है? (2)",
            "નેહાની શાળા દરિયા પાસે છે. લોખંડના દરવાજાને ઝડપથી કાટ લાગે છે, પણ 'સ્ટેનલેસ' લખેલી સ્ટીલની રેલિંગને નહિ. ઇલેક્ટ્રિશિયન તાર જોડવા સોલ્ડર વાપરે છે, અને તેનાં દાદીની બંગડીઓ 22 કૅરેટ સોનાની છે.\n\n"
            "(i) લોખંડને કાટ લાગવા કઈ બે પરિસ્થિતિઓ જરૂરી છે? (1)\n\n(ii) સ્ટેનલેસ સ્ટીલમાં લોખંડ સાથે ભેળવેલી ધાતુઓનાં નામ આપો. (1)\n\n(iii) સોલ્ડર વીજળીના તાર જોડવા માટે યોગ્ય કેમ છે? અથવા ઘરેણાંમાં 24 કૅરેટને બદલે 22 કૅરેટ સોનું કેમ વપરાય છે? (2)"),
    {0: ("(i) वायु (ऑक्सीजन) और जल (नमी)।", "(i) હવા (ઑક્સિજન) અને પાણી (ભેજ)."), 1: ("(ii) निकेल और क्रोमियम।", "(ii) નિકલ અને ક્રોમિયમ."),
     2: ("(iii) सोल्डर लेड और टिन का कम गलनांक वाला मिश्रातु है, इसलिए आसानी से पिघलकर तारों को जोड़ देता है। अथवा शुद्ध (24 कैरेट) सोना बहुत नरम है; 2 भाग चाँदी या ताँबा मिलाने से वह कठोर हो जाता है।",
         "(iii) સોલ્ડર લેડ અને ટિનની નીચા ગલનબિંદુવાળી મિશ્રધાતુ છે, તેથી સહેલાઈથી પીગળીને તારને જોડે છે. અથવા શુદ્ધ (24 કૅરેટ) સોનું ખૂબ નરમ છે; 2 ભાગ ચાંદી કે તાંબું ઉમેરતાં તે સખત બને છે.")})
add("cb2", ("विद्यार्थियों ने चार धातुओं P, Q, R और S के छोटे टुकड़े ठंडे जल में रखे। P ने तीव्र अभिक्रिया की और आग पकड़ ली। Q ने ठंडे जल से अभिक्रिया नहीं की पर गर्म जल से की। R ने केवल भाप से अभिक्रिया की। S ने भाप से भी अभिक्रिया नहीं की।\n\n"
            "(i) सबसे अधिक सक्रिय धातु कौन-सी है? (1)\n\n(ii) चारों धातुओं को सक्रियता के घटते क्रम में व्यवस्थित कीजिए। (1)\n\n(iii) यदि R लोहा है, तो भाप के साथ इसकी अभिक्रिया का समीकरण लिखिए। अथवा यदि S ताँबा है, तो गर्म जल के टैंकों में इसका प्रयोग क्यों होता है? (2)",
            "વિદ્યાર્થીઓએ ચાર ધાતુઓ P, Q, R અને S ના નાના ટુકડા ઠંડા પાણીમાં મૂક્યા. P એ તીવ્ર પ્રક્રિયા કરી અને સળગી ઊઠી. Q એ ઠંડા પાણી સાથે પ્રક્રિયા ન કરી પણ ગરમ પાણી સાથે કરી. R એ ફક્ત વરાળ સાથે પ્રક્રિયા કરી. S એ વરાળ સાથે પણ પ્રક્રિયા ન કરી.\n\n"
            "(i) સૌથી વધુ સક્રિય ધાતુ કઈ છે? (1)\n\n(ii) ચારેય ધાતુઓને ઘટતી સક્રિયતાના ક્રમમાં ગોઠવો. (1)\n\n(iii) જો R લોખંડ હોય, તો વરાળ સાથે તેની પ્રક્રિયાનું સમીકરણ લખો. અથવા જો S તાંબું હોય, તો ગરમ પાણીની ટાંકીમાં તે કેમ વપરાય છે? (2)"),
    {0: ("(i) P।", "(i) P."), 1: ("(ii) P > Q > R > S।", "(ii) P > Q > R > S."), 2: ("(iii) {0} अथवा ताँबा जल या भाप से अभिक्रिया नहीं करता, इसलिए संक्षारित नहीं होता, और ऊष्मा का अच्छा चालक है।", "(iii) {0} અથવા તાંબું પાણી કે વરાળ સાથે પ્રક્રિયા કરતું નથી, તેથી તેનું ક્ષારણ થતું નથી, અને તે ઉષ્માનું સારું વાહક છે.")})

# Assertion-reason
_CORRECT = re.compile(r"^Correct! A is (?:true|false): (.*) R is (?:true|false): (.*)$")
def ar(key, a, r, wa, wr, ex):
    it = item(key)
    a_en, r_en = it["question"].replace("**Assertion (A):** ", "").split("\n\n**Reason (R):** ")
    wa_en, wr_en = _CORRECT.match(it["option_feedback"][it["correct_index"]]).groups()
    (a_hi, a_gu), (r_hi, r_gu) = fill(a_en, *a), fill(r_en, *r)
    (wa_hi, wa_gu), (wr_hi, wr_gu), (ex_hi, ex_gu) = fill(wa_en, *wa), fill(wr_en, *wr), fill(it["explanation"], *ex)
    return (a_hi, r_hi, a_gu, r_gu, wa_hi, wr_hi, wa_gu, wr_gu, ex_hi, ex_gu)
